<span class="line"><span style="color:#ABB2BF;">    *</span><span style="color:#E06C75;">.tar.gz</span><span style="color:#ABB2BF;">)    </span><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;Gzip 压缩包&quot;</span><span style="color:#ABB2BF;"> ;;</span></span>
