<span class="line"><span style="color:#E06C75;">    Makefile</span><span style="color:#ABB2BF;">)    </span><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;Make 构建文件&quot;</span><span style="color:#ABB2BF;"> ;;</span></span>
